package location

import (
	_ "embed"
	"strings"

	"github.com/strelov1/freehire/internal/platform/stringset"
)

// metrosTSV is generated by cmd/gen-metros: every GeoNames place the city dictionary
// can read, with the GHS-FUA functional urban area it lies in ("Sacramento (US)") or an
// empty value when it lies in none.
//
//go:embed metros.tsv
var metrosTSV string

type metroKey struct{ name, country, admin1 string }

var metroByPlace, metroByName = loadMetros(metrosTSV)

// loadMetros returns the exact (name, country, admin1) table and the bare-name table.
// Both follow one rule: a key is kept only when every line carrying it names the same
// metro, and "no metro" (an empty value) counts as a metro of its own. A bare name like
// "Roseville" in the US is three places in three metros; bare "Jackson" is Jackson NJ
// in a metro and Jackson MS in none, which is just as ambiguous — answering with the
// only metro on file would label the larger city with its namesake's metro. An exact
// key repeated under two values is the same ambiguity one level down. Ambiguous keys
// are left out; a key whose one value is "no metro" stays in, mapped to "", so a stated
// subdivision can still disagree with it. Neither table ever answers "" as a metro —
// metroFor filters it.
func loadMetros(tsv string) (map[metroKey]string, map[[2]string]string) {
	exact := map[metroKey]string{}
	exactAmbiguous := map[metroKey]bool{}
	seen := map[[2]string]string{}
	ambiguous := map[[2]string]bool{}
	for _, line := range strings.Split(tsv, "\n") {
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		f := strings.Split(line, "\t")
		if len(f) != 4 {
			continue
		}
		ek := metroKey{f[0], f[1], f[2]}
		if prev, ok := exact[ek]; ok && prev != f[3] {
			exactAmbiguous[ek] = true
		}
		exact[ek] = f[3]
		k := [2]string{f[0], f[1]}
		if prev, ok := seen[k]; ok && prev != f[3] {
			ambiguous[k] = true
		}
		seen[k] = f[3]
	}
	for k := range exactAmbiguous {
		delete(exact, k)
	}
	for k := range ambiguous {
		delete(seen, k)
	}
	return exact, seen
}

// metroFor resolves one city of a location line. stated is the set of US/CA subdivision
// codes the line names. With none, the bare-name table answers. With any, it never does:
// a line that states a subdivision has said where its cities are, and a bare-name guess
// for a city those subdivisions do not place would invent a metro ("Folsom, PA; Austin,
// TX" must not yield Folsom's California metro). Each stated code is tried exactly, and
// the city resolves only when they all agree on one metro.
//
// A place the table records as in no metro is a known answer, not a missing one: it
// takes part in that agreement ("Jackson, MS / NJ" names two places, one of them in no
// metro, and gets nothing) and is never returned as a metro.
func metroFor(cityName, country string, stated map[string]struct{}) (string, bool) {
	name := strings.ToLower(cityName)
	if len(stated) == 0 {
		v := metroByName[[2]string{name, country}]
		return v, v != ""
	}
	found, seen := "", false
	for code := range stated {
		v, ok := metroByPlace[metroKey{name, country, code}]
		if !ok {
			continue
		}
		if seen && found != v {
			return "", false
		}
		found, seen = v, true
	}
	return found, found != ""
}

// MetrosForCities resolves cities an adapter supplied as structured data, all in one
// country, to their metros by bare name alone — the same rule a location line naming no
// subdivision follows. Unknown, ambiguous and in-no-metro cities contribute nothing.
func MetrosForCities(cities []string, country string) []string {
	set := map[string]struct{}{}
	for _, c := range cities {
		if v, ok := metroFor(c, country, nil); ok {
			set[v] = struct{}{}
		}
	}
	return stringset.Sorted(set)
}
